mockup.css:
.mock-section-quote-band { background: #14332a; color: #f0ece0; font-family: var(--f-serif);
  display: flex; flex-direction: column; justify-content: center; gap: 2.6cqw; padding: 0 9cqw; }
.mock-section-quote-band blockquote { margin: 0; font-size: 4.4cqw; line-height: 1.16; letter-spacing: -.015em; }
.mock-section-quote-band cite { font-style: normal; font-family: var(--f-sans); font-size: 1.35cqw;
  letter-spacing: .16em; text-transform: uppercase; opacity: .6; }
